INSERT INTO public.applications (id, cycle_id, position_id, person_id, stage, alias, answers, university, degree_program, study_year, languages, heard_from, cv_file_id, consent_at, consent_version, decision_reason, decided_at, decided_by, offer_sent_at, offer_responded_at, submitted_at, stage_changed_at, anonymized_at, created_at) VALUES
  ('8bf843c6-d337-4267-a858-29112656ca58', 'e20f6543-c922-4d74-a559-803133775d06', 'ac183a80-4a07-4eb8-9ccb-e236cb1f20ac', 'caf514ba-5122-4986-bee1-6caf1155c36c', 'interview', 'C-8BF843', '{"motivation":"I am curious about consulting but I want my first projects to matter. 180DC combines rigorous problem solving with purpose, and a community of motivated people.","impact_experience":"I co-founded a tutoring programme for refugee children in Barcelona; we grew from 6 to 40 volunteers and I built the scheduling system ourselves.","teamwork":"In a group project one teammate stopped contributing. I talked to them privately, understood they were overwhelmed, and we redistributed the work."}'::jsonb, 'ESADE Business School', 'BBA', '2nd year', ARRAY['English','Spanish'], 'Instagram', '1b7af967-c4e4-4ab9-baf1-6e5922e3641f', now() - interval '116 hours', '2026-11', NULL, NULL, NULL, NULL, NULL, now() - interval '116 hours', now() - interval '37 hours', NULL, now() - interval '116 hours'),
  ('e73e5aec-5d6e-42a5-a2b8-5de4e771904d', 'e20f6543-c922-4d74-a559-803133775d06', '3256230e-36d8-4655-b227-7a06cc7d4d5c', '49c5bec4-020c-408f-8c90-5cbbcfe4d397', 'interview', 'C-E73E5A', '{"motivation":"Your project with a circular-fashion start-up convinced me: you deliver real recommendations, not student exercises. I want to learn from that and contribute my analytical skills.","impact_experience":"As treasurer of a student sustainability club I introduced a simple impact tracker that convinced our university to fund reusable cups for all campus cafés.","teamwork":"In a group project one teammate stopped contributing. I talked to them privately, understood they were overwhelmed, and we redistributed the work."}'::jsonb, 'Universitat Pompeu Fabra', 'Economics', '3rd year', ARRAY['English','Catalan','Italian','Portuguese'], 'Instagram', '78c27526-7593-4f93-81a7-11e305272b77', now() - interval '370 hours', '2026-11', NULL, NULL, NULL, NULL, NULL, now() - interval '370 hours', now() - interval '104 hours', NULL, now() - interval '370 hours'),
  ('ee9c5933-3cd3-419c-974a-24663a5dd556', 'e20f6543-c922-4d74-a559-803133775d06', '82fdc083-f4d8-4ad7-b450-9732d6f2e496', '9ce25787-2ac2-447a-aade-256b9f6ea0aa', 'interview', 'C-EE9C59', '{"motivation":"I am curious about consulting but I want my first projects to matter. 180DC combines rigorous problem solving with purpose, and a community of motivated people.","impact_experience":"I organised a beach clean-up series with 200 participants and partnered with the city council for logistics.","teamwork":"In a group project one teammate stopped contributing. I talked to them privately, understood they were overwhelmed, and we redistributed the work.","analytics_project":"For my thesis I scraped housing listings and estimated a hedonic price model; I presented the results to the city''s housing office."}'::jsonb, 'ESADE Business School', 'Global Governance', '3rd year', ARRAY['English','Dutch'], 'Esade club fair', 'f9aa459e-5e66-4117-8d74-c52d2941d676', now() - interval '321 hours', '2026-11', NULL, NULL, NULL, NULL, NULL, now() - interval '321 hours', now() - interval '144 hours', NULL, now() - interval '321 hours'),
  ('941714f5-412e-4c9b-9e77-10bf727bbfed', 'e20f6543-c922-4d74-a559-803133775d06', '3256230e-36d8-4655-b227-7a06cc7d4d5c', 'f69835c1-da34-4a69-913b-c5e156821825', 'received', 'C-941714', '{"motivation":"Consulting looks interesting and 180DC is well known at Esade.","impact_experience":"I volunteered at a local animal shelter on weekends during high school.","teamwork":"In a group project one teammate stopped contributing. I talked to them privately, understood they were overwhelmed, and we redistributed the work."}'::jsonb, 'ESADE Business School', 'MSc Finance', '1st year', ARRAY['English','Hindi','Italian','Spanish'], 'Professor', '596914a4-f98c-445f-9967-f8fb1d9e08ec', now() - interval '17 hours', '2026-11', NULL, NULL, NULL, NULL, NULL, now() - interval '17 hours', now() - interval '17 hours', NULL, now() - interval '17 hours'),
  ('25017600-65f1-40fc-922d-9182ff941263', 'e20f6543-c922-4d74-a559-803133775d06', '82fdc083-f4d8-4ad7-b450-9732d6f2e496', '8197459d-9b9e-49dc-8357-c426996fc1ef', 'screening', 'C-250176', '{"motivation":"After volunteering with a food bank in my hometown I realised that many NGOs lack the strategic support companies take for granted. I want to bring structure and data to them.","impact_experience":"During an internship at a microfinance NGO in Colombia I analysed repayment data and proposed a new reminder process that reduced late payments.","teamwork":"In a group project one teammate stopped contributing. I talked to them privately, understood they were overwhelmed, and we redistributed the work.","analytics_project":"I built a demand-forecasting model in Python (gradient boosting) for a café chain and visualised it in Power BI; it cut food waste by 12% in a pilot."}'::jsonb, 'ESADE Business School', 'BBA', '1st year', ARRAY['English','Spanish'], 'Instagram', '288d5914-30d7-4a48-8941-8d83e1b2e7fa', now() - interval '393 hours', '2026-11', NULL, NULL, NULL, NULL, NULL, now() - interval '393 hours', now() - interval '241 hours', NULL, now() - interval '393 hours'),
  ('c9553dd7-58cd-4e27-994e-a9d74a53b414', 'e20f6543-c922-4d74-a559-803133775d06', 'ac183a80-4a07-4eb8-9ccb-e236cb1f20ac', '056ec029-8bc7-4fd5-986d-a62f78b2ddd4', 'rejected', 'C-C9553D', '{"motivation":"I would like to join because I want to grow as a team player and learn how to frame messy problems for clients who have limited resources.","impact_experience":"I organised a beach clean-up series with 200 participants and partnered with the city council for logistics.","teamwork":"Working in a hackathon team taught me to listen first and to say clearly what I can deliver by when."}'::jsonb, 'ESADE Business School', 'BBA', '2nd year', ARRAY['English','Italian','Hindi'], 'Instagram', '7a7e6233-b839-42f2-86c8-1296954e4779', now() - interval '223 hours', '2026-11', 'Answers too generic for the track; other candidates more specific.', now() - interval '74 hours', '00000000-0000-4000-8000-000000000002', NULL, NULL, now() - interval '223 hours', now() - interval '74 hours', NULL, now() - interval '223 hours'),
